reproduction_sources.content:
param([string] $Role = 'baseline', [switch] $Assertions, [switch] $Profile, [switch] $Bench)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$RepoRoot = 'C:/Users/ander/Documents/xpact'
$ProbeRoot = Join-Path $RepoRoot 'build/pubmed-position-20261026'
. "$RepoRoot/scripts/import_msvc_environment.ps1"
$env:ISE_C_COMPILER = 'msc_vc140'
$Mode = if ($Assertions) { 'FinalizedAssertions' } else { 'Finalized' }
$Kind = if ($Profile) { 'profile' } elseif ($Bench) { 'bench' } else { 'files' }
$Config = if ($Kind -eq 'files') { "$ProbeRoot/$Role.ecf" } else { "$ProbeRoot/$Role-$Kind.ecf" }
$Target = if ($Kind -eq 'files') { if ($Assertions) { 'catalog_assertions' } else { 'catalog' } } else { if ($Assertions) { 'xpact_benchmarks_assertions' } else { 'xpact_benchmarks' } }
$Name = if ($Kind -eq 'files') { 'xpact_file_benchmark.exe' } else { 'xpact_benchmarks.exe' }
$Project = "$ProbeRoot/projects/$Role/$Kind/$Mode"
New-Item -ItemType Directory -Force -Path $Project | Out-Null
$CompilerArgs = @('-batch', '-clean', '-finalize')
if ($Assertions) { $CompilerArgs += '-keep' }
$CompilerArgs += @('-config', $Config, '-target', $Target, '-project_path', $Project)
& ec @CompilerArgs *> "$ProbeRoot/logs/$Role-$Kind-$Mode-eiffel.log"
if ($LASTEXITCODE -ne 0) { Get-Content "$ProbeRoot/logs/$Role-$Kind-$Mode-eiffel.log" -Tail 45; throw 'Eiffel build failed' }
$CodeDir = "$Project/EIFGENs/$Target/F_code"
Push-Location $CodeDir
try {
    & finish_freezing *> "$ProbeRoot/logs/$Role-$Kind-$Mode-c.log"
    if ($LASTEXITCODE -ne 0) { Get-Content "$ProbeRoot/logs/$Role-$Kind-$Mode-c.log" -Tail 45; throw 'C build failed' }
} finally { Pop-Location }
Write-Host "$CodeDir/$Name"
